function tightestSpread(scores: number[], k: number): number {
  let best = Infinity;
  for (const low of scores) {
    // the lowest member counts itself among the scores >= low
    const above = scores.filter(s => s >= low).sort((a, b) => a - b);
    if (above.length >= k) best = Math.min(best, above[k - 1] - low);
  }
  return best;
}

